const linhas = $input.all().map((i) => i.json);

// Sem campanha vigente hoje a query não devolve linha nenhuma.
if (linhas.length === 0) {
  return [];
}

// Regra da farmácia (01/10/2026): menos de 60 clientes ofertados na
// semana da campanha = perde 1% da comissão da semana. Desde 02/10 também
// é piso pro PRÊMIO — o número vem da campanha (ofertas_minimas_periodo);
// 60 é só o padrão se a campanha não tiver.
const META_OFERTAS_PADRAO = 60;

// Disparo das 14:20 é parcial do dia; o das 21:50 fecha o dia.
const horaSP = Number(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo', hour: '2-digit', hour12: false }));
const parcial = horaSP < 18;

const c = linhas[0];
const metaOferta = Number(c.meta_clientes_ofertados_dia) || 0;
const valorMin = Number(c.valor_minimo) || 0;
const qtdMin = Number(c.quantidade_minima) || 0;
const ofertasMin = Number(c.ofertas_minimas_periodo) || 0;
const META_OFERTAS_SEMANA = ofertasMin || META_OFERTAS_PADRAO;

let premios = c.premiacao_ranking;
if (typeof premios === 'string') premios = JSON.parse(premios);
premios = (premios || []).map((p) => ({ posicao: Number(p.posicao), valor: Number(p.valor) }));
premios.sort((a, b) => a.posicao - b.posicao);
const premioDe = (posicao) => premios.find((p) => p.posicao === posicao)?.valor;

function brl(v) {
  return (Number(v) || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 });
}
const plural = (n, um, varios) => `${n} ${Number(n) === 1 ? um : varios}`;
const MEDALHAS = { 1: '🥇', 2: '🥈', 3: '🥉' };

const vendedores = linhas.map((l) => ({
  nome: l.nome,
  trabalhou: l.trabalhou_hoje === true || l.trabalhou_hoje === 't',
  ofertados: l.ofertados_hoje == null ? null : Number(l.ofertados_hoje),
  ofertadosSemana: Number(l.ofertados_semana) || 0,
  itensHoje: Number(l.itens_hoje) || 0,
  valor: Number(l.valor_periodo) || 0,
  itens: Number(l.itens_periodo) || 0,
}));

// Ranking igual ao do app (lib/vendaComplementar.ts): todo mundo que
// marcou item, por valor; prêmio só pra quem bate os 3 pisos (valor,
// itens, ofertas). Quem não bate fica na posição SEM prêmio — o prêmio
// não passa pro próximo.
const faltaPraConcorrer = (v) => {
  const falta = [];
  if (valorMin > 0 && v.valor < valorMin) falta.push(brl(valorMin - v.valor));
  if (qtdMin > 0 && v.itens < qtdMin) falta.push(plural(qtdMin - v.itens, 'item', 'itens'));
  if (ofertasMin > 0 && v.ofertadosSemana < ofertasMin) falta.push(plural(ofertasMin - v.ofertadosSemana, 'oferta', 'ofertas'));
  return falta.join(' e ');
};
const ranking = vendedores
  .filter((v) => v.itens > 0)
  .sort((a, b) => b.valor - a.valor || b.itens - a.itens);
ranking.forEach((v, i) => {
  v.posicao = i + 1;
  v.falta = faltaPraConcorrer(v);
  v.premio = v.falta ? null : premioDe(v.posicao) ?? null;
});

const partes = [];
partes.push('🛒 *Vendas Complementares*');
partes.push(`📅 ${c.hoje_txt}${parcial ? ' · parcial das 14h' : ''} · dia ${c.dia_atual} de ${c.total_dias} (${c.inicio_txt} a ${c.fim_txt})`);

// 1) Oferecimentos de hoje — foco principal
const doDia = vendedores
  .filter((v) => v.trabalhou || v.ofertados != null)
  .sort((a, b) => (b.ofertados ?? -1) - (a.ofertados ?? -1));
if (doDia.length > 0) {
  partes.push('');
  const titulo = parcial ? 'Clientes ofertados hoje (até agora)' : 'Clientes ofertados hoje';
  partes.push(metaOferta > 0 ? `📣 *${titulo}* (meta: ${metaOferta} por dia)` : `📣 *${titulo}*`);
  let totalOfertas = 0;
  for (const v of doDia) {
    const semana = ` · semana ${v.ofertadosSemana}/${META_OFERTAS_SEMANA}`;
    const vendeu = v.itensHoje > 0 ? ` · vendeu ${plural(v.itensHoje, 'item', 'itens')}` : '';
    if (v.ofertados == null || v.ofertados === 0) {
      partes.push(`❌ ${v.nome} — não registrou${semana}${vendeu}`);
      continue;
    }
    totalOfertas += v.ofertados;
    const icone = metaOferta > 0 && v.ofertados >= metaOferta ? '✅' : '⚠️';
    partes.push(`${icone} ${v.nome} — hoje ${v.ofertados}${semana}${vendeu}`);
  }
  const bateram = doDia.filter((v) => metaOferta > 0 && (v.ofertados ?? 0) >= metaOferta).length;
  partes.push(metaOferta > 0
    ? `Time: ${totalOfertas} ofertas · ${bateram} de ${doDia.length} bateram a meta`
    : `Time: ${totalOfertas} ofertas`);
}

// 1b) Regra das 60 ofertas na semana — todo mundo que trabalhou no período
const abaixo60 = vendedores
  .filter((v) => v.ofertadosSemana < META_OFERTAS_SEMANA)
  .sort((a, b) => a.ofertadosSemana - b.ofertadosSemana);
partes.push('');
partes.push(`🎯 *Meta da semana: ${META_OFERTAS_SEMANA} clientes ofertados*`);
partes.push(`Quem não chegar a ${META_OFERTAS_SEMANA} até ${c.fim_txt} perde *1% da comissão da semana*.`);
if (abaixo60.length === 0) {
  partes.push('Todo mundo já cumpriu! 💪');
} else {
  partes.push(`Ainda faltam: ${abaixo60.map((v) => `${v.nome} (${META_OFERTAS_SEMANA - v.ofertadosSemana})`).join(' · ')}`);
}

// 2) Acumulado no período — todo mundo, pros vendedores acompanharem.
partes.push('');
partes.push(`💰 *Acumulado no período* (${c.inicio_txt} a ${c.fim_txt})`);
if (ranking.some((v) => v.premio != null)) partes.push('👏 Parabéns a quem já está levando prêmio!');
for (const v of ranking) {
  const rotulo = v.premio != null ? MEDALHAS[v.posicao] ?? `${v.posicao}º` : `${v.posicao}º`;
  const final = v.premio != null
    ? ` → hoje leva ${brl(v.premio)}`
    : v.falta ? ` (faltam ${v.falta}${premioDe(v.posicao) ? ' pro prêmio' : ''})` : '';
  partes.push(`${rotulo} ${v.nome} — ${brl(v.valor)} · ${plural(v.itens, 'item', 'itens')} · ${plural(v.ofertadosSemana, 'oferta', 'ofertas')}${final}`);
}
for (const v of vendedores.filter((x) => x.itens === 0)) {
  const falta = faltaPraConcorrer(v);
  partes.push(`• ${v.nome} — ${brl(0)} · 0 itens · ${plural(v.ofertadosSemana, 'oferta', 'ofertas')}${falta ? ` (faltam ${falta})` : ''}`);
}
if (ranking.length === 0) partes.push('Ninguém marcou complementar ainda — o 1º lugar está em aberto!');

// 4) Prêmio e regra
partes.push('');
const linhaPremios = premios.map((p) => `${p.posicao}º ${brl(p.valor)}`).join(' · ');
if (linhaPremios) partes.push(`🏆 Prêmios: ${linhaPremios}`);
const regra = [];
if (valorMin > 0) regra.push(brl(valorMin));
if (qtdMin > 0) regra.push(plural(qtdMin, 'item', 'itens'));
if (ofertasMin > 0) regra.push(`${ofertasMin} clientes ofertados`);
if (regra.length > 0) partes.push(`Pra concorrer, no mínimo: ${regra.join(' e ')} até ${c.fim_txt}`);
const restantes = Number(c.dias_restantes);
partes.push(restantes > 0 ? `⏳ ${plural(restantes, 'dia', 'dias')} pra virar o jogo!` : '⏳ Último dia!');

return [{ json: { mensagem: partes.join('\n') } }];
